using System.Collections.Generic;

namespace AllIn.Holdem.Brain
{
    /// <summary>
    /// The 169 starting-hand classes ranked by equity against one random hand (generated by
    /// `dotnet run --project tools/dotnet-harness -- gen169 200000`; AA 0.852 … 32o 0.323).
    /// "Top N%" is combo-weighted: pairs 6 combos, suited 4, offsuit 12, out of 1,326.
    /// </summary>
    public static class HandRanks
    {
        public static readonly string[] Order =
        {
            "AA", "KK", "QQ", "JJ", "TT", "99", "88", "AKs", "77", "AQs", "AJs", "AKo", "ATs",
            "AQo", "AJo", "KQs", "66", "ATo", "A9s", "KJs", "A8s", "KTs", "KQo", "A7s", "A9o", "KJo",
            "55", "A6s", "QJs", "A5s", "K9s", "A8o", "KTo", "QTs", "A4s", "A7o", "K8s", "A3s", "QJo",
            "K9o", "K7s", "A5o", "JTs", "Q9s", "A6o", "A2s", "QTo", "44", "A4o", "K6s", "K8o", "Q8s",
            "A3o", "K5s", "J9s", "Q9o", "JTo", "K7o", "A2o", "K4s", "Q7s", "K6o", "J8s", "K3s", "T9s",
            "33", "Q6s", "Q8o", "K5o", "J9o", "K2s", "Q5s", "T8s", "J7s", "K4o", "Q4s", "Q7o", "T9o",
            "J8o", "K3o", "Q3s", "Q6o", "98s", "K2o", "J6s", "T7s", "22", "Q5o", "Q2s", "J5s", "T8o",
            "J7o", "97s", "Q4o", "T6s", "J4s", "Q3o", "J3s", "98o", "87s", "T7o", "J6o", "Q2o", "96s",
            "J2s", "T5s", "J5o", "T4s", "J4o", "86s", "97o", "T6o", "T3s", "76s", "95s", "J3o", "87o",
            "T2s", "85s", "J2o", "96o", "T5o", "94s", "75s", "T4o", "93s", "86o", "65s", "84s", "95o",
            "92s", "T3o", "76o", "74s", "T2o", "85o", "54s", "64s", "83s", "75o", "94o", "93o", "82s",
            "73s", "65o", "53s", "63s", "84o", "92o", "43s", "74o", "72s", "54o", "64o", "52s", "62s",
            "83o", "42s", "82o", "73o", "63o", "32s", "53o", "43o", "72o", "52o", "62o", "42o", "32o",
        };

        static readonly Dictionary<string, int> RankOf = new Dictionary<string, int>();
        static readonly double[] TopPercent = new double[169]; // cumulative, including the class itself

        static HandRanks()
        {
            int combos = 0;
            for (int i = 0; i < Order.Length; i++)
            {
                RankOf[Order[i]] = i;
                combos += Combos(Order[i]);
                TopPercent[i] = combos * 100.0 / 1326;
            }
        }

        public static int Combos(string cls) => cls.Length == 2 ? 6 : cls[2] == 's' ? 4 : 12;

        public static string ClassOf(int c0, int c1)
        {
            int r0 = Card.Rank(c0), r1 = Card.Rank(c1);
            int hi = r0 > r1 ? r0 : r1, lo = r0 > r1 ? r1 : r0;
            if (hi == lo) return "" + Card.Ranks[hi] + Card.Ranks[lo];
            return "" + Card.Ranks[hi] + Card.Ranks[lo] + (Card.Suit(c0) == Card.Suit(c1) ? "s" : "o");
        }

        /// <summary>1 = AA … 169 = 32o.</summary>
        public static int Rank(int c0, int c1) => RankOf[ClassOf(c0, c1)] + 1;

        /// <summary>Where this hand sits in "top N%" terms (AA ≈ 0.45, 32o = 100).</summary>
        public static double Percentile(int c0, int c1) => TopPercent[RankOf[ClassOf(c0, c1)]];
    }
}
